describe('Password Reset Confirmation Message', () => {
  const testEmail = 'testuser@example.com';
  const newPassword = 'NewSecurePassword123!';
  const resetToken = 'valid-reset-token-12345';

  beforeEach(() => {
    cy.visit('/password-reset');
    cy.clearCookies();
    cy.clearLocalStorage();
  });

  it('should display confirmation message after successful password reset', () => {
    cy.get('input[name="email"]').type(testEmail);
    cy.get('button[type="submit"]').click();

    cy.url().should('include', '/reset-password');
    cy.get('input[name="token"]').should('exist');

    cy.get('input[name="newPassword"]').type(newPassword);
    cy.get('input[name="confirmPassword"]').type(newPassword);
    cy.get('button[type="submit"]').contains('Reset Password').click();

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Password has been successfully reset');
    cy.get('[data-testid="success-message"]').should('have.class', 'alert-success');
  });

  it('should handle password reset with mismatched passwords and show error', () => {
    cy.get('input[name="email"]').type(testEmail);
    cy.get('button[type="submit"]').click();

    cy.url().should('include', '/reset-password');

    cy.get('input[name="newPassword"]').type(newPassword);
    cy.get('input[name="confirmPassword"]').type('DifferentPassword123!');
    cy.get('button[type="submit"]').contains('Reset Password').click();

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Passwords do not match');
    cy.get('[data-testid="success-message"]').should('not.exist');
  });

  it('should redirect to login page after successful password reset confirmation', () => {
    cy.get('input[name="email"]').type(testEmail);
    cy.get('button[type="submit"]').click();

    cy.get('input[name="newPassword"]').type(newPassword);
    cy.get('input[name="confirmPassword"]').type(newPassword);
    cy.get('button[type="submit"]').contains('Reset Password').click();

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('a[href="/login"]').should('be.visible').click();

    cy.url().should('include', '/login');
  });

  it('should display error message for expired reset token', () => {
    cy.visit(`/password-reset?token=expired-token-xyz`);

    cy.get('input[name="newPassword"]').type(newPassword);
    cy.get('input[name="confirmPassword"]').type(newPassword);
    cy.get('button[type="submit"]').contains('Reset Password').click();

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Reset link has expired');
  });
});
